import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export const DEFAULT_SCARE_MONSTER_TURNS = 10;

export type ScareMonsterScrollOptions = ScrollItemOptions;

/**
 * Scroll of Scare Monster (`驚嚇怪物卷軸`) — terrifies all living monsters within the
 * player's line of sight (`VISIBLE` tiles) for 10 turns, forcing them to flee in panic.
 */
export class ScareMonsterScroll extends ScrollItem {
  public readonly scrollKind = 'scare_monster' as const;

  constructor(options: ScareMonsterScrollOptions) {
    super({
      id: options.id ?? `scare-monster-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Scare Monster',
      itemTypeId: 'scare_monster_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'A dread-inscribed scroll that causes nearby monsters in sight to flee in terror for 10 turns.',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '視野恐懼 10 回合' : 'Terrify 10t (FOV)';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): ScareMonsterScroll {
    return new ScareMonsterScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('scare_monster_scroll');
