import { Actor } from '../core/entities/Actor';
import { GameWorld, VisualEffectEvent, VisualEffectKind } from '../core/GameWorld';
import { findShortestPath } from '../core/Pathfinder';
import { Tile } from '../core/Tile';
import {
  DoorState,
  isAdjacent,
  Point,
  pointsEqual,
  TileType,
  VisibilityState,
} from '../core/types';
import { Camera } from './Camera';
import { SpriteKey, SpriteManager } from './SpriteManager';

export interface HoverTileState {
  readonly position: Point;
  readonly shiftKey: boolean;
}

export interface ThrowPreviewState {
  readonly cursor: Point;
  readonly maxRange?: number;
  readonly isRangedMagic?: boolean;
  readonly isRangedCharge?: boolean;
  readonly isShadowBlink?: boolean;
  readonly piercesLine?: boolean;
}

export interface FlyingProjectileState {
  readonly spriteKey: string;
  readonly worldPosition: { readonly x: number; readonly y: number };
}

export const DEFAULT_VISUAL_EFFECT_DURATION_MS = 220;
export const PROJECTILE_VFX_STEP_MS = 18;

export const SUPPORTED_VISUAL_EFFECT_KINDS: readonly VisualEffectKind[] = [
  'melee_hit',
  'projectile_hit',
  'potion_shatter',
  'skill_bite',
  'skill_pierce',
  'skill_bash',
  'skill_hide',
  'skill_roar',
  'skill_tough',
  'skill_charge',
  'skill_shadow_strike',
  'skill_acid',
  'skill_clever',
  'skill_fireball',
  'skill_rock_missile',
  'skill_rock_pierce',
  'skill_shield',
  'skill_scud',
] as const;

export interface ActiveVisualEffect {
  readonly id: number;
  readonly event: VisualEffectEvent;
  readonly startTimeMs: number;
  readonly flightDurationMs: number;
  readonly durationMs: number;
  readonly floorNumber?: number;
}

/**
 * 2D HTML5 Canvas renderer that draws the dungeon map centered on the player:
 * - UNEXPLORED tiles: solid dark void (#07080d)
 * - EXPLORED tiles (Fog of War): 32x32 terrain sprite + dark overlay (hiding items/enemies)
 * - VISIBLE tiles (In Sight): full-brightness 32x32 terrain sprite + visible items & enemies + player at center
 */
export class CanvasRenderer {
  public readonly canvas: HTMLCanvasElement;
  public readonly ctx: CanvasRenderingContext2D;
  public readonly camera: Camera;
  public readonly sprites: SpriteManager;
  private hoverState: HoverTileState | null = null;
  private throwPreview: ThrowPreviewState | null = null;
  private flyingProjectile: FlyingProjectileState | null = null;
  private readonly activeVisualEffects: ActiveVisualEffect[] = [];
  private nextVisualEffectId = 0;
  private boundWorld: GameWorld | null = null;
  private unsubscribeWorldVisualEffects: (() => void) | null = null;
  private rafId: number | null = null;

  constructor(
    canvas: HTMLCanvasElement,
    camera: Camera = new Camera(canvas.width, canvas.height),
    sprites: SpriteManager = new SpriteManager()
  ) {
    this.canvas = canvas;
    const context = canvas.getContext('2d');
    if (!context) {
      throw new Error('Failed to acquire 2D rendering context from canvas');
    }
    this.ctx = context;
    this.camera = camera;
    this.sprites = sprites;
  }

  public setHoverTile(hover: HoverTileState | null): void {
    this.hoverState = hover;
  }

  public setThrowPreview(preview: ThrowPreviewState | null): void {
    this.throwPreview = preview;
  }

  public setFlyingProjectile(projectile: FlyingProjectileState | null): void {
    this.flyingProjectile = projectile;
  }

  public setTileSize(tileSize: number): void {
    this.camera.setTileSize(tileSize);
  }

  private getNowMs(): number {
    return typeof performance !== 'undefined' && typeof performance.now === 'function'
      ? performance.now()
      : Date.now();
  }

  public getVisualEffectDurationMs(kind: VisualEffectKind): number {
    switch (kind) {
      case 'skill_rock_pierce':
        return 280;
      case 'skill_hide':
      case 'skill_roar':
      case 'skill_tough':
      case 'skill_shadow_strike':
      case 'skill_acid':
      case 'skill_clever':
      case 'skill_fireball':
      case 'skill_rock_missile':
      case 'skill_shield':
      case 'skill_scud':
        return 240;
      case 'melee_hit':
      case 'projectile_hit':
      case 'potion_shatter':
      case 'skill_bite':
      case 'skill_pierce':
      case 'skill_bash':
      case 'skill_charge':
        return DEFAULT_VISUAL_EFFECT_DURATION_MS;
    }
  }

  public bindWorldVisualEffects(world: GameWorld): void {
    if (this.boundWorld === world && this.unsubscribeWorldVisualEffects !== null) {
      return;
    }
    if (this.unsubscribeWorldVisualEffects) {
      this.unsubscribeWorldVisualEffects();
      this.unsubscribeWorldVisualEffects = null;
    }
    this.clearVisualEffects();
    this.boundWorld = world;
    this.unsubscribeWorldVisualEffects = world.subscribeVisualEffects(
      (event) => {
        this.enqueueVisualEffect(event, undefined, world.currentFloor);
      },
      () => {
        this.clearVisualEffects();
      }
    );
  }

  public enqueueVisualEffect(
    event: VisualEffectEvent,
    nowMs?: number,
    floorNumber?: number
  ): ActiveVisualEffect {
    const baseNow = nowMs ?? this.getNowMs();
    const delay = Math.max(0, event.delayMs ?? 0);
    const flightSegments =
      event.projectileSpriteKey && event.flightPath && event.flightPath.length >= 2
        ? event.flightPath.length - 1
        : 0;
    const active: ActiveVisualEffect = {
      id: ++this.nextVisualEffectId,
      event,
      startTimeMs: baseNow + delay,
      flightDurationMs: flightSegments * PROJECTILE_VFX_STEP_MS,
      durationMs: this.getVisualEffectDurationMs(event.kind),
      floorNumber: floorNumber ?? this.boundWorld?.currentFloor,
    };
    this.activeVisualEffects.push(active);
    if (nowMs === undefined) {
      this.scheduleVisualEffectFrame();
    }
    return active;
  }

  public clearVisualEffects(): void {
    this.activeVisualEffects.length = 0;
    if (this.rafId !== null && typeof cancelAnimationFrame === 'function') {
      cancelAnimationFrame(this.rafId);
    }
    this.rafId = null;
  }

  public getActiveVisualEffects(): readonly ActiveVisualEffect[] {
    return [...this.activeVisualEffects];
  }

  private scheduleVisualEffectFrame(): void {
    if (
      this.rafId !== null ||
      this.activeVisualEffects.length === 0 ||
      this.boundWorld === null ||
      typeof requestAnimationFrame !== 'function'
    ) {
      return;
    }
    this.rafId = requestAnimationFrame(() => {
      this.rafId = null;
      if (!this.boundWorld || this.activeVisualEffects.length === 0) {
        return;
      }
      this.render(this.boundWorld, this.getNowMs());
      if (this.activeVisualEffects.length > 0) {
        this.scheduleVisualEffectFrame();
      }
    });
  }

  public render(world: GameWorld, nowMs?: number): void {
    const { ctx, camera } = this;
    const width = this.canvas.width;
    const height = this.canvas.height;
    camera.resizeViewport(width, height);

    const tileSize = camera.tileSize;
    const playerPos = world.player.position;

    // Disable smoothing so 32x32 pixel-art sprites scale with crisp edges at any tileSize
    ctx.imageSmoothingEnabled = false;

    // 1. Clear viewport with unexplored dark background
    ctx.fillStyle = '#07080d';
    ctx.fillRect(0, 0, width, height);

    // 2. Render visible & explored map tiles within camera bounds
    const bounds = camera.getVisibleTileBounds(playerPos, world.map.width, world.map.height);

    for (let y = bounds.minY; y <= bounds.maxY; y++) {
      for (let x = bounds.minX; x <= bounds.maxX; x++) {
        const tile = world.map.getTile(x, y);
        if (!tile || tile.visibility === VisibilityState.UNEXPLORED) {
          continue;
        }

        const screenPos = camera.worldToScreen({ x, y }, playerPos);
        const spriteKey = this.getTerrainSpriteKey(tile);
        this.drawSprite(spriteKey, screenPos.x, screenPos.y, tileSize);

        // Render revealed floor traps above static terrain (so VISIBLE tiles show full brightness
        // and EXPLORED tiles retain remembered trap locations dimmed under the Fog of War overlay)
        const revealedTrap = world.getRevealedTrapAt({ x, y });
        if (revealedTrap && this.sprites.hasSprite(revealedTrap.spriteKey)) {
          this.drawSprite(revealedTrap.spriteKey, screenPos.x, screenPos.y, tileSize);
        }

        // If tile is in EXPLORED Fog of War, darken it and hide dynamic contents
        if (tile.visibility === VisibilityState.EXPLORED) {
          ctx.fillStyle = 'rgba(5, 8, 18, 0.65)';
          ctx.fillRect(screenPos.x, screenPos.y, tileSize, tileSize);
        }
      }
    }

    // 3. Render items on currently VISIBLE tiles only:
    //    - 1 item stack on tile -> item's own sprite icon
    //    - 2+ item stacks on tile -> dedicated 'item_bag' loot sack icon
    const renderedItemTiles = new Set<string>();
    for (const item of world.getVisibleItems()) {
      const tileKey = `${item.position.x},${item.position.y}`;
      if (renderedItemTiles.has(tileKey)) {
        continue;
      }
      renderedItemTiles.add(tileKey);

      const spriteKey = this.getTileItemSpriteKey(world, item.position);
      if (spriteKey) {
        const screenPos = camera.worldToScreen(item.position, playerPos);
        this.drawSprite(spriteKey, screenPos.x, screenPos.y, tileSize);
      }
    }

    // 4. Render enemies on currently VISIBLE tiles only (semi-transparent at 0.45 alpha if Invisible & revealed by See Invisible, plus tiny HP bar overlay if damaged)
    for (const enemy of world.getVisibleEnemies()) {
      const screenPos = camera.worldToScreen(enemy.position, playerPos);
      const validKey: SpriteKey = this.sprites.hasSprite(enemy.spriteKey)
        ? enemy.spriteKey
        : 'enemy_goblin';
      if (enemy.isInvisible()) {
        ctx.save();
        ctx.globalAlpha = 0.45;
        this.drawSprite(validKey, screenPos.x, screenPos.y, tileSize);
        ctx.restore();
      } else {
        this.drawSprite(validKey, screenPos.x, screenPos.y, tileSize);
      }
      this.drawDamagedActorHpBar(enemy, screenPos, tileSize);
    }

    // 5. Render the player figure at the exact center of the screen (semi-transparent at 0.4 alpha when Invisible, plus crisp HP bar overlay if damaged)
    const playerScreen = camera.worldToScreen(playerPos, playerPos);
    if (world.player.isInvisible()) {
      ctx.save();
      ctx.globalAlpha = 0.4;
      this.drawSprite('player_human', playerScreen.x, playerScreen.y, tileSize);
      ctx.restore();
    } else {
      this.drawSprite('player_human', playerScreen.x, playerScreen.y, tileSize);
    }
    this.drawDamagedActorHpBar(world.player, playerScreen, tileSize);

    // 6. Render Throw Targeting dotted trajectory preview OR mouse hover / auto-travel path preview
    if (this.throwPreview) {
      this.renderThrowTrajectoryPreview(world, this.throwPreview);
    } else if (this.hoverState) {
      this.renderHoverHighlight(world, this.hoverState);
    }

    // 7. Render in-flight thrown item sprite overlay
    if (this.flyingProjectile) {
      this.renderFlyingProjectileOverlay(world, this.flyingProjectile);
    }

    // 8. Render non-blocking combat, projectile, and proactive skill visual effect overlays
    if (this.activeVisualEffects.length > 0) {
      this.renderVisualEffects(world, nowMs);
    }
  }

  /**
   * Draws a compact 2px-tall health bar across the top of `actor`'s tile whenever `hp < maxHp`.
   * Returns `true` if a bar was drawn, or `false` if the actor is at full HP.
   */
  public drawDamagedActorHpBar(actor: Actor, screenPos: Point, tileSize: number): boolean {
    if (actor.stats.maxHp <= 0 || actor.stats.hp >= actor.stats.maxHp) {
      return false;
    }

    const barWidth = Math.max(8, tileSize - 4);
    const barHeight = Math.max(2, Math.floor(tileSize / 16));
    const ratio = Math.max(0, Math.min(1, actor.stats.hp / actor.stats.maxHp));
    const fillWidth = actor.stats.hp > 0 ? Math.max(1, Math.round(barWidth * ratio)) : 0;

    this.ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
    this.ctx.fillRect(screenPos.x + 2, screenPos.y + 1, barWidth, barHeight);
    if (fillWidth > 0) {
      this.ctx.fillStyle = ratio > 0.4 ? '#22c55e' : '#ef4444';
      this.ctx.fillRect(screenPos.x + 2, screenPos.y + 1, fillWidth, barHeight);
    }
    return true;
  }

  /**
   * Determines which 32x32 sprite key should represent items on a visible tile:
   * - 0 items -> null
   * - 1 item stack -> that item's own spriteKey
   * - 2+ item stacks -> 'item_bag'
   */
  public getTileItemSpriteKey(world: GameWorld, pos: Point): SpriteKey | null {
    if (!world.isTileVisible(pos)) {
      return null;
    }
    const itemsAtTile = world.getItemsAt(pos);
    if (itemsAtTile.length === 0) {
      return null;
    }
    if (itemsAtTile.length >= 2) {
      return 'item_bag';
    }
    const singleKey = world.getItemEffectiveSpriteKey(itemsAtTile[0]);
    return this.sprites.hasSprite(singleKey) ? singleKey : 'item_chest';
  }

  private getTerrainSpriteKey(tile: Tile): SpriteKey {
    if (tile.type === TileType.WALL) {
      return 'tile_wall';
    }
    if (tile.type === TileType.WATER) {
      return 'tile_water';
    }
    if (tile.type === TileType.DOOR) {
      const effectiveState =
        tile.visibility === VisibilityState.VISIBLE ? tile.doorState : tile.lastSeenDoorState;
      return effectiveState === DoorState.OPEN ? 'tile_door_open' : 'tile_door_closed';
    }
    if (tile.type === TileType.STAIRS_UP) {
      return 'tile_stairs_up';
    }
    if (tile.type === TileType.STAIRS_DOWN) {
      return 'tile_stairs_down';
    }
    if (tile.type === TileType.PORTAL) {
      return 'tile_portal';
    }
    return 'tile_floor';
  }

  private drawSprite(key: SpriteKey, screenX: number, screenY: number, size: number): void {
    const spriteCanvas = this.sprites.getSpriteCanvas(key);
    if (spriteCanvas) {
      this.ctx.drawImage(spriteCanvas, screenX, screenY, size, size);
    }
  }

  private renderHoverHighlight(world: GameWorld, hover: HoverTileState): void {
    const tile = world.map.getTile(hover.position.x, hover.position.y);
    if (!tile) {
      return;
    }
    const playerPos = world.player.position;
    const size = this.camera.tileSize;
    if (tile.visibility === VisibilityState.UNEXPLORED) {
      if (world.player.isBlind() && isAdjacent(playerPos, hover.position)) {
        this.ctx.save();
        this.ctx.lineWidth = 2;
        const screenPos = this.camera.worldToScreen(hover.position, playerPos);
        this.ctx.strokeStyle = 'rgba(148, 163, 184, 0.75)';
        this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
        this.ctx.restore();
      }
      return;
    }

    this.ctx.save();
    this.ctx.lineWidth = 2;

    // 1. Hovering over the player's own tile ('@'): cyan highlight (Pick Up items or Wait 1 turn)
    if (pointsEqual(hover.position, playerPos)) {
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      this.ctx.strokeStyle = 'rgba(56, 189, 248, 0.9)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    // 2. Shift + Hover on an adjacent tile: emerald highlight if Dash-passable, red if blocked
    if (hover.shiftKey && isAdjacent(playerPos, hover.position)) {
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      const blocker = world.getBlockingActorAt(hover.position);
      const actorVisibleBlock = blocker !== null && world.canPlayerSeeActor(blocker);
      const moveType = world.player.movementType;
      const standingTile = world.map.getTile(playerPos.x, playerPos.y);
      const blockedByWaterDash =
        moveType === 'walking' &&
        (standingTile?.type === TileType.WATER || tile.type === TileType.WATER);
      const effectivePassable =
        tile.visibility === VisibilityState.VISIBLE
          ? tile.canBeTraversedBy(moveType)
          : (tile.canBeTraversedBy(moveType) && tile.type !== TileType.DOOR) ||
            (moveType !== 'swimming' &&
              tile.type === TileType.DOOR &&
              tile.lastSeenDoorState === DoorState.OPEN);
      const canDash = effectivePassable && !actorVisibleBlock && !blockedByWaterDash;
      this.ctx.strokeStyle = canDash
        ? 'rgba(16, 185, 129, 0.95)'
        : 'rgba(239, 68, 68, 0.85)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    // 3. Compute shortest path through known tiles
    const path = findShortestPath(world, playerPos, hover.position);
    if (!path || path.length === 0) {
      // Blocked or unreachable tile: red border on hovered tile
      const screenPos = this.camera.worldToScreen(hover.position, playerPos);
      this.ctx.strokeStyle = 'rgba(239, 68, 68, 0.8)';
      this.ctx.strokeRect(screenPos.x + 1, screenPos.y + 1, size - 2, size - 2);
      this.ctx.restore();
      return;
    }

    const enemyVisible = world.getVisibleEnemies().length > 0;
    const markerSize = Math.max(4, Math.floor(size * 0.22));
    const markerOffset = Math.floor((size - markerSize) / 2);

    if (enemyVisible) {
      // Tactical 1-turn mode: highlight only the 1st step in amber/cyan
      const firstStepScreen = this.camera.worldToScreen(path[0], playerPos);
      this.ctx.fillStyle = 'rgba(245, 158, 11, 0.85)';
      this.ctx.fillRect(
        firstStepScreen.x + markerOffset,
        firstStepScreen.y + markerOffset,
        markerSize,
        markerSize
      );
      this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.95)';
      this.ctx.strokeRect(firstStepScreen.x + 1, firstStepScreen.y + 1, size - 2, size - 2);

      if (path.length > 1) {
        const destScreen = this.camera.worldToScreen(hover.position, playerPos);
        this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.45)';
        this.ctx.strokeRect(destScreen.x + 1, destScreen.y + 1, size - 2, size - 2);
      }
      this.ctx.restore();
      return;
    }

    // Full path preview: draw cyan breadcrumb squares along intermediate path steps
    this.ctx.fillStyle = 'rgba(56, 189, 248, 0.75)';
    for (let i = 0; i < path.length - 1; i++) {
      const stepScreen = this.camera.worldToScreen(path[i], playerPos);
      this.ctx.fillRect(
        stepScreen.x + markerOffset,
        stepScreen.y + markerOffset,
        markerSize,
        markerSize
      );
    }

    // Highlight destination tile (amber for closed door, green for passable floor/open door)
    const destScreen = this.camera.worldToScreen(hover.position, playerPos);
    const effectiveDoorState =
      tile.visibility === VisibilityState.VISIBLE ? tile.doorState : tile.lastSeenDoorState;
    const isDestClosedDoor =
      tile.type === TileType.DOOR && effectiveDoorState === DoorState.CLOSED;

    this.ctx.strokeStyle = isDestClosedDoor
      ? 'rgba(245, 158, 11, 0.95)'
      : 'rgba(74, 222, 128, 0.9)';
    this.ctx.strokeRect(destScreen.x + 1, destScreen.y + 1, size - 2, size - 2);
    this.ctx.restore();
  }

  private renderThrowTrajectoryPreview(world: GameWorld, preview: ThrowPreviewState): void {
    const playerPos = world.player.position;
    const size = this.camera.tileSize;

    if (preview.isShadowBlink) {
      const blink = world.computeShadowBlinkPreview(preview.cursor, preview.maxRange ?? 5);
      this.ctx.save();
      this.ctx.lineWidth = 2;

      if (blink.landingTile && !pointsEqual(blink.landingTile, blink.targetCursor)) {
        const landScreen = this.camera.worldToScreen(blink.landingTile, playerPos);
        this.ctx.fillStyle = 'rgba(139, 92, 246, 0.28)';
        this.ctx.fillRect(landScreen.x + 2, landScreen.y + 2, size - 4, size - 4);
        this.ctx.strokeStyle = 'rgba(192, 132, 252, 0.92)';
        this.ctx.strokeRect(landScreen.x + 2, landScreen.y + 2, size - 4, size - 4);
      }

      const cursorScreen = this.camera.worldToScreen(blink.targetCursor, playerPos);
      if (blink.hitActor && !blink.blocked) {
        this.ctx.strokeStyle = 'rgba(248, 113, 113, 0.98)';
      } else if (blink.blocked) {
        this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.95)';
      } else {
        this.ctx.strokeStyle = 'rgba(168, 85, 247, 0.95)';
      }
      this.ctx.strokeRect(cursorScreen.x + 1, cursorScreen.y + 1, size - 2, size - 2);

      const tick = Math.max(3, Math.floor(size * 0.18));
      const x0 = cursorScreen.x + 3;
      const y0 = cursorScreen.y + 3;
      const x1 = cursorScreen.x + size - 3;
      const y1 = cursorScreen.y + size - 3;
      this.ctx.beginPath();
      this.ctx.moveTo(x0, y0 + tick);
      this.ctx.lineTo(x0, y0);
      this.ctx.lineTo(x0 + tick, y0);
      this.ctx.moveTo(x1 - tick, y0);
      this.ctx.lineTo(x1, y0);
      this.ctx.lineTo(x1, y0 + tick);
      this.ctx.moveTo(x0, y1 - tick);
      this.ctx.lineTo(x0, y1);
      this.ctx.lineTo(x0 + tick, y1);
      this.ctx.moveTo(x1 - tick, y1);
      this.ctx.lineTo(x1, y1);
      this.ctx.lineTo(x1, y1 - tick);
      this.ctx.stroke();

      this.ctx.restore();
      return;
    }

    const trajectory = preview.isRangedCharge
      ? world.computeChargePreviewTrajectory(preview.cursor, preview.maxRange ?? 5)
      : preview.isRangedMagic
        ? preview.piercesLine
          ? world.computeLineMagicPreviewTrajectory(preview.cursor, preview.maxRange ?? 5)
          : world.computeRangedMagicPreviewTrajectory(preview.cursor, preview.maxRange ?? 8)
        : world.computeThrowPreviewTrajectory(preview.cursor);

    this.ctx.save();
    this.ctx.lineWidth = 2;

    const markerSize = Math.max(4, Math.floor(size * 0.22));
    const markerOffset = Math.floor((size - markerSize) / 2);

    if (preview.piercesLine && trajectory.flightPath.length > 0) {
      // Highlight EVERY tile on the line-piercing Rock Pierce path (crimson on visible foes, amber-stone on floor)
      for (const step of trajectory.flightPath) {
        const stepScreen = this.camera.worldToScreen(step, playerPos);
        const actorOnStep = world.getBlockingActorAt(step);
        const isVisibleEnemy = Boolean(
          actorOnStep &&
            !actorOnStep.isPlayer &&
            actorOnStep.isAlive() &&
            world.canPlayerSeeActor(actorOnStep)
        );
        this.ctx.fillStyle = isVisibleEnemy
          ? 'rgba(248, 113, 113, 0.24)'
          : 'rgba(245, 158, 11, 0.20)';
        this.ctx.fillRect(stepScreen.x + 2, stepScreen.y + 2, size - 4, size - 4);
        this.ctx.strokeStyle = isVisibleEnemy
          ? 'rgba(248, 113, 113, 0.92)'
          : 'rgba(251, 191, 36, 0.85)';
        this.ctx.strokeRect(stepScreen.x + 2, stepScreen.y + 2, size - 4, size - 4);
      }
    } else if (trajectory.flightPath.length > 1) {
      // Draw dotted breadcrumb markers along intermediate flight steps (matching Auto-Travel style)
      this.ctx.fillStyle = 'rgba(251, 191, 36, 0.88)';
      for (let i = 0; i < trajectory.flightPath.length - 1; i++) {
        const stepScreen = this.camera.worldToScreen(trajectory.flightPath[i], playerPos);
        this.ctx.fillRect(
          stepScreen.x + markerOffset,
          stepScreen.y + markerOffset,
          markerSize,
          markerSize
        );
      }
    }

    // If the cursor lies beyond an intercepting enemy or wall, draw a subtle dashed outline on cursor
    if (!pointsEqual(trajectory.targetCursor, trajectory.impactTile)) {
      const cursorScreen = this.camera.worldToScreen(trajectory.targetCursor, playerPos);
      this.ctx.save();
      this.ctx.setLineDash([4, 3]);
      this.ctx.strokeStyle = 'rgba(148, 163, 184, 0.65)';
      this.ctx.strokeRect(cursorScreen.x + 2, cursorScreen.y + 2, size - 4, size - 4);
      this.ctx.restore();
    }

    // Highlight the actual impact/landing tile with a targeting reticle
    const impactScreen = this.camera.worldToScreen(trajectory.impactTile, playerPos);
    if (trajectory.hitActor) {
      this.ctx.strokeStyle = 'rgba(248, 113, 113, 0.98)';
    } else if (trajectory.blockedByObstacle) {
      this.ctx.strokeStyle = 'rgba(245, 158, 11, 0.95)';
    } else {
      this.ctx.strokeStyle = 'rgba(56, 189, 248, 0.95)';
    }
    this.ctx.strokeRect(impactScreen.x + 1, impactScreen.y + 1, size - 2, size - 2);

    // Corner crosshair ticks inside reticle
    const tick = Math.max(3, Math.floor(size * 0.18));
    const x0 = impactScreen.x + 3;
    const y0 = impactScreen.y + 3;
    const x1 = impactScreen.x + size - 3;
    const y1 = impactScreen.y + size - 3;
    this.ctx.beginPath();
    this.ctx.moveTo(x0, y0 + tick);
    this.ctx.lineTo(x0, y0);
    this.ctx.lineTo(x0 + tick, y0);
    this.ctx.moveTo(x1 - tick, y0);
    this.ctx.lineTo(x1, y0);
    this.ctx.lineTo(x1, y0 + tick);
    this.ctx.moveTo(x0, y1 - tick);
    this.ctx.lineTo(x0, y1);
    this.ctx.lineTo(x0 + tick, y1);
    this.ctx.moveTo(x1 - tick, y1);
    this.ctx.lineTo(x1, y1);
    this.ctx.lineTo(x1, y1 - tick);
    this.ctx.stroke();

    this.ctx.restore();
  }

  private renderFlyingProjectileOverlay(world: GameWorld, proj: FlyingProjectileState): void {
    const playerPos = world.player.position;
    const size = this.camera.tileSize;
    const center = this.camera.getCenterTileScreenOrigin();
    const screenX = Math.round((proj.worldPosition.x - playerPos.x) * size + center.x);
    const screenY = Math.round((proj.worldPosition.y - playerPos.y) * size + center.y);

    const validKey: SpriteKey = this.sprites.hasSprite(proj.spriteKey)
      ? proj.spriteKey
      : 'item_chest';

    this.ctx.save();
    this.ctx.fillStyle = 'rgba(251, 191, 36, 0.22)';
    this.ctx.beginPath();
    this.ctx.arc(screenX + size / 2, screenY + size / 2, Math.max(6, size * 0.36), 0, Math.PI * 2);
    this.ctx.fill();
    this.drawSprite(validKey, screenX, screenY, size);
    this.ctx.restore();
  }

  /**
   * Prunes expired or off-floor visual effects and renders all currently active overlays.
   * Returns the number of effects drawn on this frame.
   */
  public renderVisualEffects(world: GameWorld, nowMs?: number): number {
    if (this.activeVisualEffects.length === 0) {
      return 0;
    }
    const now = nowMs ?? this.getNowMs();
    const playerPos = world.player.position;
    const size = this.camera.tileSize;
    let drawn = 0;

    for (let i = this.activeVisualEffects.length - 1; i >= 0; i--) {
      const fx = this.activeVisualEffects[i];
      if (fx.floorNumber !== undefined && fx.floorNumber !== world.currentFloor) {
        this.activeVisualEffects.splice(i, 1);
        continue;
      }
      if (now >= fx.startTimeMs + fx.flightDurationMs + fx.durationMs) {
        this.activeVisualEffects.splice(i, 1);
      }
    }

    for (const fx of this.activeVisualEffects) {
      if (now < fx.startTimeMs) {
        continue;
      }
      if (
        fx.flightDurationMs > 0 &&
        now < fx.startTimeMs + fx.flightDurationMs &&
        fx.event.projectileSpriteKey &&
        fx.event.flightPath &&
        fx.event.flightPath.length >= 2
      ) {
        const segCount = fx.event.flightPath.length - 1;
        const scaled =
          Math.max(0, Math.min(0.999999, (now - fx.startTimeMs) / fx.flightDurationMs)) * segCount;
        const segIdx = Math.min(segCount - 1, Math.floor(scaled));
        const localT = scaled - segIdx;
        const p0 = fx.event.flightPath[segIdx];
        const p1 = fx.event.flightPath[segIdx + 1];
        this.renderFlyingProjectileOverlay(world, {
          spriteKey: fx.event.projectileSpriteKey,
          worldPosition: {
            x: p0.x + (p1.x - p0.x) * localT,
            y: p0.y + (p1.y - p0.y) * localT,
          },
        });
        drawn += 1;
        continue;
      }
      const impactStart = fx.startTimeMs + fx.flightDurationMs;
      const progress = Math.max(0, Math.min(1, (now - impactStart) / fx.durationMs));
      const screenPos = this.camera.worldToScreen(fx.event.targetPos, playerPos);
      this.drawVisualEffectOverlay(fx.event, screenPos, size, progress);
      drawn += 1;
    }

    return drawn;
  }

  private drawVisualEffectOverlay(
    event: VisualEffectEvent,
    screenPos: Point,
    size: number,
    progress: number
  ): void {
    const { ctx } = this;
    const cx = screenPos.x + size / 2;
    const cy = screenPos.y + size / 2;
    const fade = Math.max(0.08, 1 - progress * progress);

    ctx.save();
    ctx.globalAlpha = fade;

    switch (event.kind) {
      case 'melee_hit': {
        const sweep = Math.min(1, progress * 1.45);
        const reach = size * 0.38;
        const xStart = cx + reach;
        const yStart = cy - reach;
        const xEnd = xStart - reach * 2 * sweep;
        const yEnd = yStart + reach * 2 * sweep;

        if (event.isCrit) {
          // Critical hit: expanding crimson-gold shockwave ring + twin cross-slash
          ctx.lineWidth = Math.max(2, size * 0.08);
          ctx.strokeStyle = 'rgba(239, 68, 68, 0.92)';
          ctx.beginPath();
          ctx.arc(cx, cy, size * (0.16 + 0.34 * progress), 0, Math.PI * 2);
          ctx.stroke();

          ctx.lineWidth = Math.max(3, size * 0.12);
          ctx.strokeStyle = '#dc2626';
          ctx.beginPath();
          ctx.moveTo(xStart, yStart);
          ctx.lineTo(xEnd, yEnd);
          ctx.moveTo(cx - reach, yStart);
          ctx.lineTo(cx - reach + reach * 2 * sweep, yEnd);
          ctx.stroke();

          ctx.lineWidth = Math.max(1.5, size * 0.055);
          ctx.strokeStyle = '#fde047';
          ctx.beginPath();
          ctx.moveTo(xStart, yStart);
          ctx.lineTo(xEnd, yEnd);
          ctx.moveTo(cx - reach, yStart);
          ctx.lineTo(cx - reach + reach * 2 * sweep, yEnd);
          ctx.stroke();
        } else {
          // Normal hit: crisp steel-white diagonal slash arc + impact sparks
          ctx.lineWidth = Math.max(2.5, size * 0.1);
          ctx.strokeStyle = '#cbd5e1';
          ctx.beginPath();
          ctx.arc(cx, cy, size * 0.34, -Math.PI * 0.35, -Math.PI * 0.35 + Math.PI * 0.85 * sweep);
          ctx.stroke();

          ctx.lineWidth = Math.max(1.5, size * 0.06);
          ctx.strokeStyle = '#ffffff';
          ctx.beginPath();
          ctx.moveTo(xStart, yStart);
          ctx.lineTo(xEnd, yEnd);
          ctx.stroke();
        }

        // Radial impact sparks
        const sparkInner = size * (0.08 + 0.14 * progress);
        const sparkOuter = size * (0.2 + 0.24 * progress);
        ctx.lineWidth = Math.max(1.2, size * 0.045);
        ctx.strokeStyle = event.isCrit ? '#fef08a' : '#f8fafc';
        ctx.beginPath();
        for (let s = 0; s < 4; s++) {
          const angle = Math.PI * 0.25 + (s * Math.PI) / 2;
          ctx.moveTo(cx + Math.cos(angle) * sparkInner, cy + Math.sin(angle) * sparkInner);
          ctx.lineTo(cx + Math.cos(angle) * sparkOuter, cy + Math.sin(angle) * sparkOuter);
        }
        ctx.stroke();
        break;
      }

      case 'projectile_hit': {
        // Kinetic shockwave ring + 6 radial amber-white impact sparks
        ctx.fillStyle = 'rgba(251, 191, 36, 0.28)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.12 + 0.18 * (1 - progress)), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2, size * 0.075);
        ctx.strokeStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.12 + 0.32 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const innerR = size * (0.1 + 0.14 * progress);
        const outerR = size * (0.22 + 0.24 * progress);
        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = '#f8fafc';
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + 0.25;
          ctx.moveTo(cx + Math.cos(angle) * innerR, cy + Math.sin(angle) * innerR);
          ctx.lineTo(cx + Math.cos(angle) * outerR, cy + Math.sin(angle) * outerR);
        }
        ctx.stroke();
        break;
      }

      case 'potion_shatter': {
        const [lr, lg, lb] = event.tintRgb ?? [56, 189, 248];
        const [hr, hg, hb] = event.highlightRgb ?? [186, 230, 253];

        // Translucent liquid splash pool
        ctx.fillStyle = `rgba(${lr}, ${lg}, ${lb}, 0.32)`;
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.22 * progress), 0, Math.PI * 2);
        ctx.fill();

        // Expanding liquid ring
        ctx.lineWidth = Math.max(2, size * 0.075);
        ctx.strokeStyle = `rgb(${lr}, ${lg}, ${lb})`;
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.12 + 0.32 * progress), 0, Math.PI * 2);
        ctx.stroke();

        // 8 outward-flying bottle-tinted droplets
        const dropDist = size * (0.1 + 0.34 * progress);
        const dropRadius = Math.max(1.5, size * 0.065 * (1 - 0.35 * progress));
        for (let i = 0; i < 8; i++) {
          const angle = (i * Math.PI) / 4 + 0.2;
          const dx = Math.cos(angle) * dropDist;
          const dy = Math.sin(angle) * dropDist - size * 0.04 * (1 - progress);
          ctx.fillStyle = i % 2 === 0 ? `rgb(${hr}, ${hg}, ${hb})` : `rgb(${lr}, ${lg}, ${lb})`;
          ctx.beginPath();
          ctx.arc(cx + dx, cy + dy, dropRadius, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_bite': {
        // Upper & lower ivory/crimson fangs snapping together toward center + blood sparks
        const snap = Math.min(1, progress * 1.55);
        const jawGap = size * (0.36 * (1 - snap) + 0.03);
        const fangHalfW = size * 0.075;
        const fangLen = size * 0.18;
        const offsets = [-size * 0.2, 0, size * 0.2];

        ctx.lineWidth = Math.max(1.2, size * 0.04);
        ctx.strokeStyle = '#dc2626';
        ctx.fillStyle = '#fef2f2';

        for (const ox of offsets) {
          const fx = cx + ox;
          // Upper fang pointing down
          const topY = cy - jawGap - fangLen * 0.5;
          const tipUpperY = topY + fangLen;
          ctx.beginPath();
          ctx.moveTo(fx - fangHalfW, topY);
          ctx.lineTo(fx + fangHalfW, topY);
          ctx.lineTo(fx, tipUpperY);
          ctx.lineTo(fx - fangHalfW, topY);
          ctx.fill();
          ctx.stroke();

          // Lower fang pointing up
          const botY = cy + jawGap + fangLen * 0.5;
          const tipLowerY = botY - fangLen;
          ctx.beginPath();
          ctx.moveTo(fx - fangHalfW, botY);
          ctx.lineTo(fx + fangHalfW, botY);
          ctx.lineTo(fx, tipLowerY);
          ctx.lineTo(fx - fangHalfW, botY);
          ctx.fill();
          ctx.stroke();
        }

        if (event.isCrit) {
          ctx.lineWidth = Math.max(2, size * 0.07);
          ctx.strokeStyle = '#fde047';
          ctx.beginPath();
          ctx.arc(cx, cy, size * (0.16 + 0.3 * progress), 0, Math.PI * 2);
          ctx.stroke();
        }

        // Crimson blood-spark burst
        const burstR = size * (0.08 + 0.28 * progress);
        ctx.fillStyle = '#ef4444';
        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + 0.35;
          ctx.beginPath();
          ctx.arc(
            cx + Math.cos(angle) * burstR,
            cy + Math.sin(angle) * burstR,
            Math.max(1.4, size * 0.055),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }

      case 'skill_pierce': {
        // Thrusting golden-amber lance streak (angled along originPos -> targetPos when visible) + armor-shatter shards
        let ux = 0;
        let uy = -1;
        if (
          event.originPos &&
          (event.originPos.x !== event.targetPos.x || event.originPos.y !== event.targetPos.y)
        ) {
          const rawDx = event.targetPos.x - event.originPos.x;
          const rawDy = event.targetPos.y - event.originPos.y;
          const len = Math.hypot(rawDx, rawDy) || 1;
          ux = rawDx / len;
          uy = rawDy / len;
        }

        const thrust = Math.min(1, progress * 1.5);
        const tailDist = size * (0.44 - 0.16 * thrust);
        const tipDist = size * (-0.1 + 0.48 * thrust);
        const tailX = cx - ux * tailDist;
        const tailY = cy - uy * tailDist;
        const tipX = cx + ux * tipDist;
        const tipY = cy + uy * tipDist;

        ctx.lineWidth = Math.max(3, size * 0.12);
        ctx.strokeStyle = event.isCrit ? '#dc2626' : '#f59e0b';
        ctx.beginPath();
        ctx.moveTo(tailX, tailY);
        ctx.lineTo(tipX, tipY);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.055);
        ctx.strokeStyle = '#fef08a';
        ctx.beginPath();
        ctx.moveTo(tailX, tailY);
        ctx.lineTo(tipX, tipY);
        ctx.stroke();

        // Radial steel/gold armor-shatter sparks
        const shardIn = size * (0.08 + 0.12 * progress);
        const shardOut = size * (0.2 + 0.26 * progress);
        ctx.lineWidth = Math.max(1.5, size * 0.05);
        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + 0.5;
          ctx.strokeStyle = i % 2 === 0 ? '#93c5fd' : '#fde047';
          ctx.beginPath();
          ctx.moveTo(cx + Math.cos(angle) * shardIn, cy + Math.sin(angle) * shardIn);
          ctx.lineTo(cx + Math.cos(angle) * shardOut, cy + Math.sin(angle) * shardOut);
          ctx.stroke();
        }
        break;
      }

      case 'skill_bash': {
        // Concussive amber-gold impact flash + twin shockwave rings + orbiting stun stars
        const flashR = size * (0.16 * (1 - 0.5 * progress));
        ctx.fillStyle = event.isCrit ? 'rgba(239, 68, 68, 0.85)' : 'rgba(251, 191, 36, 0.82)';
        ctx.beginPath();
        ctx.arc(cx, cy, Math.max(2, flashR), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2.5, size * 0.09);
        ctx.strokeStyle = event.isCrit ? '#dc2626' : '#d97706';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.12 + 0.34 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.055);
        ctx.strokeStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.07 + 0.22 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const starOrbitR = size * (0.18 + 0.2 * progress);
        const starY = cy - size * 0.1;
        for (let i = 0; i < 5; i++) {
          const angle = (i * Math.PI * 2) / 5 + progress * 2.4;
          const sx = cx + Math.cos(angle) * starOrbitR;
          const sy = starY + Math.sin(angle) * starOrbitR * 0.55;
          ctx.fillStyle = i % 2 === 0 ? '#fef08a' : '#fde047';
          ctx.beginPath();
          ctx.arc(sx, sy, Math.max(1.6, size * 0.055), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_hide': {
        // Swirling indigo-silver shadow smoke rings + rising translucent mist wisps
        ctx.lineWidth = Math.max(2, size * 0.07);
        ctx.strokeStyle = 'rgba(99, 102, 241, 0.85)';
        ctx.beginPath();
        ctx.arc(cx, cy + size * 0.08, size * (0.14 + 0.28 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = 'rgba(148, 163, 184, 0.85)';
        ctx.beginPath();
        ctx.arc(cx, cy - size * 0.04, size * (0.1 + 0.22 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const wispOffsets = [-0.24, -0.12, 0, 0.12, 0.24];
        for (let i = 0; i < wispOffsets.length; i++) {
          const wx = cx + size * wispOffsets[i];
          const wy = cy + size * (0.2 - 0.48 * progress) - (i % 2) * size * 0.06;
          ctx.fillStyle =
            i % 2 === 0 ? 'rgba(79, 70, 229, 0.55)' : 'rgba(203, 213, 225, 0.5)';
          ctx.beginPath();
          ctx.arc(wx, wy, Math.max(2, size * 0.08 * (1 - 0.25 * progress)), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_acid': {
        // Sizzling emerald-lime corrosive splash puddle + rising bright-green acid bubbles
        ctx.fillStyle = 'rgba(16, 185, 129, 0.34)';
        ctx.beginPath();
        ctx.arc(cx, cy + size * 0.08, size * (0.16 + 0.22 * progress), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2, size * 0.07);
        ctx.strokeStyle = '#84cc16';
        ctx.beginPath();
        ctx.arc(cx, cy + size * 0.06, size * (0.14 + 0.28 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const bubbleSpec = [
          { ox: -0.22, oy: 0.14, r: 0.065 },
          { ox: -0.08, oy: 0.2, r: 0.08 },
          { ox: 0.08, oy: 0.12, r: 0.07 },
          { ox: 0.22, oy: 0.18, r: 0.06 },
          { ox: 0, oy: 0.02, r: 0.075 },
        ];
        for (let i = 0; i < bubbleSpec.length; i++) {
          const b = bubbleSpec[i];
          const bx = cx + size * b.ox;
          const by = cy + size * (b.oy - 0.42 * progress);
          const br = Math.max(1.5, size * b.r * (1 - 0.2 * progress));
          ctx.fillStyle = i % 2 === 0 ? '#bef264' : '#4ade80';
          ctx.beginPath();
          ctx.arc(bx, by, br, 0, Math.PI * 2);
          ctx.fill();
          ctx.lineWidth = 1;
          ctx.strokeStyle = '#15803d';
          ctx.stroke();
        }
        break;
      }

      case 'skill_clever': {
        // Radiant cyan-gold arcane rune halo + rising insight sparkle motes
        ctx.lineWidth = Math.max(2, size * 0.07);
        ctx.strokeStyle = 'rgba(56, 189, 248, 0.9)';
        ctx.beginPath();
        ctx.arc(cx, cy - size * 0.1, size * (0.14 + 0.24 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = '#fde047';
        ctx.beginPath();
        ctx.arc(cx, cy - size * 0.1, size * (0.08 + 0.16 * progress), 0, Math.PI * 2);
        ctx.stroke();

        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + progress * 0.8;
          const dist = size * (0.14 + 0.22 * progress);
          const sx = cx + Math.cos(angle) * dist;
          const sy = cy - size * (0.06 + 0.26 * progress) + Math.sin(angle) * dist * 0.55;
          ctx.fillStyle = i % 2 === 0 ? '#fef08a' : '#67e8f9';
          ctx.beginPath();
          ctx.arc(sx, sy, Math.max(1.5, size * 0.055 * (1 - 0.2 * progress)), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_fireball': {
        // Blazing crimson-orange-gold fireball explosion rings + radial ember sparks
        ctx.fillStyle = 'rgba(249, 115, 22, 0.38)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.28 * progress), 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = 'rgba(254, 240, 138, 0.7)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.18 * (1 - 0.55 * progress)), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2.5, size * 0.09);
        ctx.strokeStyle = '#ef4444';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.34 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = '#fde047';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.1 + 0.24 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const emberDist = size * (0.12 + 0.36 * progress);
        for (let i = 0; i < 8; i++) {
          const angle = (i * Math.PI) / 4 + 0.18;
          const ex = cx + Math.cos(angle) * emberDist;
          const ey = cy + Math.sin(angle) * emberDist;
          ctx.fillStyle = i % 2 === 0 ? '#fde047' : '#fb923c';
          ctx.beginPath();
          ctx.arc(ex, ey, Math.max(1.5, size * 0.06 * (1 - 0.3 * progress)), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_charge': {
        // Kinetic bull-rush speed-lines along charge vector + bronze-gold shockwave chevron & dust burst
        let ux = 1;
        let uy = 0;
        if (
          event.originPos &&
          (event.originPos.x !== event.targetPos.x || event.originPos.y !== event.targetPos.y)
        ) {
          const rawDx = event.targetPos.x - event.originPos.x;
          const rawDy = event.targetPos.y - event.originPos.y;
          const len = Math.hypot(rawDx, rawDy) || 1;
          ux = rawDx / len;
          uy = rawDy / len;
        }
        const px = -uy;
        const py = ux;

        // Three parallel speed streaks rushing into impact center
        ctx.lineWidth = Math.max(2, size * 0.075);
        ctx.strokeStyle = event.isCrit ? '#fef08a' : '#fbbf24';
        for (const lane of [-0.2, 0, 0.2]) {
          const lx = cx + px * size * lane;
          const ly = cy + py * size * lane;
          ctx.beginPath();
          ctx.moveTo(lx - ux * size * (0.48 - 0.2 * progress), ly - uy * size * (0.48 - 0.2 * progress));
          ctx.lineTo(lx + ux * size * 0.18 * progress, ly + uy * size * 0.18 * progress);
          ctx.stroke();
        }

        // Heavy shockwave ring at impact point
        ctx.lineWidth = Math.max(2.5, size * 0.09);
        ctx.strokeStyle = event.isCrit ? '#ef4444' : '#f97316';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.32 * progress), 0, Math.PI * 2);
        ctx.stroke();

        // Dust & debris puffs fanning outward
        const dustDist = size * (0.12 + 0.32 * progress);
        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + 0.25;
          ctx.fillStyle = i % 2 === 0 ? '#fde68a' : '#d97706';
          ctx.beginPath();
          ctx.arc(
            cx + Math.cos(angle) * dustDist,
            cy + Math.sin(angle) * dustDist,
            Math.max(1.5, size * 0.06 * (1 - 0.25 * progress)),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }

      case 'skill_rock_missile': {
        // Shattering stone boulder shockwave + flying jagged granite/amber shards & dust cloud
        ctx.fillStyle = 'rgba(180, 142, 96, 0.34)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.28 * progress), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2.5, size * 0.085);
        ctx.strokeStyle = '#b45309';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.12 + 0.32 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = '#fde68a';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.08 + 0.2 * progress), 0, Math.PI * 2);
        ctx.stroke();

        const shardDist = size * (0.1 + 0.36 * progress);
        const shardSize = Math.max(2, size * 0.08 * (1 - 0.25 * progress));
        for (let i = 0; i < 7; i++) {
          const angle = (i * Math.PI * 2) / 7 + 0.22;
          const sx = cx + Math.cos(angle) * shardDist;
          const sy = cy + Math.sin(angle) * shardDist;
          ctx.fillStyle = i % 2 === 0 ? '#d6d3d1' : '#f59e0b';
          ctx.beginPath();
          ctx.arc(sx, sy, shardSize * 0.65, 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_shield': {
        // Golden-amber hexagonal stone-iron ward barrier + pulsing defensive rune nodes
        const hexRadius = size * (0.24 + 0.16 * progress);
        ctx.fillStyle = 'rgba(251, 191, 36, 0.22)';
        ctx.beginPath();
        for (let i = 0; i <= 6; i++) {
          const angle = -Math.PI / 2 + ((i % 6) * Math.PI) / 3;
          const vx = cx + Math.cos(angle) * hexRadius;
          const vy = cy + Math.sin(angle) * hexRadius;
          if (i === 0) {
            ctx.moveTo(vx, vy);
          } else {
            ctx.lineTo(vx, vy);
          }
        }
        ctx.fill();

        ctx.lineWidth = Math.max(2.2, size * 0.08);
        ctx.strokeStyle = '#fbbf24';
        ctx.stroke();

        ctx.lineWidth = Math.max(1.4, size * 0.045);
        ctx.strokeStyle = '#e2e8f0';
        ctx.beginPath();
        ctx.arc(cx, cy, hexRadius * 0.68, 0, Math.PI * 2);
        ctx.stroke();

        for (let i = 0; i < 6; i++) {
          const angle = -Math.PI / 2 + (i * Math.PI) / 3;
          ctx.fillStyle = '#fef08a';
          ctx.beginPath();
          ctx.arc(
            cx + Math.cos(angle) * hexRadius,
            cy + Math.sin(angle) * hexRadius,
            Math.max(1.5, size * 0.055),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }

      case 'skill_scud': {
        // Swirling cyan-emerald gale rings + rushing diagonal wind-streak lines & silver wind motes
        ctx.lineWidth = Math.max(2, size * 0.075);
        ctx.strokeStyle = 'rgba(45, 212, 191, 0.92)';
        ctx.beginPath();
        ctx.arc(
          cx,
          cy + size * 0.06,
          size * (0.16 + 0.26 * progress),
          Math.PI * 0.1,
          Math.PI * 1.75
        );
        ctx.stroke();

        ctx.lineWidth = Math.max(1.5, size * 0.05);
        ctx.strokeStyle = '#67e8f9';
        ctx.beginPath();
        ctx.arc(
          cx,
          cy - size * 0.08,
          size * (0.12 + 0.2 * progress),
          -Math.PI * 0.85,
          Math.PI * 0.75
        );
        ctx.stroke();

        // Four rising aerodynamic speed streaks
        ctx.lineWidth = Math.max(1.6, size * 0.055);
        const lanes = [-0.26, -0.09, 0.09, 0.26];
        for (let i = 0; i < lanes.length; i++) {
          const lx = cx + size * lanes[i];
          const yBottom = cy + size * (0.34 - 0.36 * progress);
          const yTop = yBottom - size * 0.28;
          ctx.strokeStyle = i % 2 === 0 ? '#a7f3d0' : '#e0f2fe';
          ctx.beginPath();
          ctx.moveTo(lx - size * 0.06, yBottom);
          ctx.lineTo(lx + size * 0.06, yTop);
          ctx.stroke();
        }

        // Orbiting silver-mint wind motes
        for (let i = 0; i < 5; i++) {
          const angle = (i * Math.PI * 2) / 5 + progress * 1.6;
          const dist = size * (0.16 + 0.22 * progress);
          ctx.fillStyle = i % 2 === 0 ? '#f0fdfa' : '#34d399';
          ctx.beginPath();
          ctx.arc(
            cx + Math.cos(angle) * dist,
            cy + Math.sin(angle) * dist * 0.65 - size * 0.06 * progress,
            Math.max(1.4, size * 0.05),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }

      case 'skill_roar': {
        // Expanding crimson-solar battle-roar shockwave rings + radial sunburst spikes
        ctx.lineWidth = Math.max(2.2, size * 0.08);
        ctx.strokeStyle = 'rgba(239, 68, 68, 0.94)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.18 + 0.34 * progress), 0, Math.PI * 2);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.6, size * 0.055);
        ctx.strokeStyle = '#fde047';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.1 + 0.22 * progress), 0, Math.PI * 2);
        ctx.stroke();

        // Eight fierce outward starburst rays
        ctx.lineWidth = Math.max(1.8, size * 0.06);
        for (let i = 0; i < 8; i++) {
          const angle = (i * Math.PI) / 4 + progress * 0.3;
          const rInner = size * (0.14 + 0.14 * progress);
          const rOuter = size * (0.3 + 0.22 * progress);
          ctx.strokeStyle = i % 2 === 0 ? '#fbbf24' : '#f87171';
          ctx.beginPath();
          ctx.moveTo(cx + Math.cos(angle) * rInner, cy + Math.sin(angle) * rInner);
          ctx.lineTo(cx + Math.cos(angle) * rOuter, cy + Math.sin(angle) * rOuter);
          ctx.stroke();
        }
        break;
      }

      case 'skill_tough': {
        // Fortified slate-bronze hexagonal pulse + rising amber vitality pillars
        const radius = size * (0.24 + 0.18 * progress);
        ctx.lineWidth = Math.max(2.2, size * 0.08);
        ctx.strokeStyle = '#f59e0b';
        ctx.fillStyle = 'rgba(71, 85, 105, 0.35)';
        ctx.beginPath();
        for (let i = 0; i <= 6; i++) {
          const angle = ((i % 6) * Math.PI) / 3 - Math.PI / 6;
          const px = cx + Math.cos(angle) * radius;
          const py = cy + Math.sin(angle) * radius;
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.fill();
        ctx.stroke();

        // Rising golden fortitude motes
        for (let i = 0; i < 4; i++) {
          const lx = cx + size * (-0.21 + i * 0.14);
          const ly = cy + size * (0.24 - 0.38 * progress);
          ctx.fillStyle = i % 2 === 0 ? '#fde047' : '#fb923c';
          ctx.beginPath();
          ctx.arc(lx, ly, Math.max(1.6, size * 0.055), 0, Math.PI * 2);
          ctx.fill();
        }
        break;
      }

      case 'skill_rock_pierce': {
        // Erupting jagged stone piles & glowing geomantic fissure across EVERY tile of `pathTiles`!
        const tiles =
          event.pathTiles && event.pathTiles.length > 0 ? event.pathTiles : [event.targetPos];

        if (tiles.length >= 2 || event.originPos) {
          ctx.lineWidth = Math.max(2.5, size * 0.1);
          ctx.strokeStyle = 'rgba(245, 158, 11, 0.85)';
          ctx.beginPath();
          const startTile = event.originPos ?? tiles[0];
          const sx0 = screenPos.x + (startTile.x - event.targetPos.x) * size + size * 0.5;
          const sy0 = screenPos.y + (startTile.y - event.targetPos.y) * size + size * 0.5;
          ctx.moveTo(sx0, sy0);
          for (const pt of tiles) {
            const tx = screenPos.x + (pt.x - event.targetPos.x) * size + size * 0.5;
            const ty = screenPos.y + (pt.y - event.targetPos.y) * size + size * 0.5;
            ctx.lineTo(tx, ty);
          }
          ctx.stroke();
        }

        for (let idx = 0; idx < tiles.length; idx++) {
          const pt = tiles[idx];
          const tileX = screenPos.x + (pt.x - event.targetPos.x) * size;
          const tileY = screenPos.y + (pt.y - event.targetPos.y) * size;
          const tcx = tileX + size * 0.5;
          const tcy = tileY + size * 0.5;
          const stagger = tiles.length > 1 ? (idx / tiles.length) * 0.25 : 0;
          const localP = Math.max(0.15, Math.min(1, (progress - stagger) / (1 - stagger)));
          const rise = Math.sin(localP * Math.PI * 0.85);

          // Glowing fissure base ring on each path tile
          ctx.fillStyle = 'rgba(245, 158, 11, 0.32)';
          ctx.fillRect(tileX + size * 0.12, tileY + size * 0.68, size * 0.76, size * 0.18);

          // Three jagged stone-pile spikes thrusting upward on this tile
          const spikes: ReadonlyArray<[number, number, string]> = [
            [-0.22, 0.42, '#a88962'],
            [0.0, 0.62, '#d6b382'],
            [0.22, 0.46, '#927450'],
          ];
          ctx.lineWidth = Math.max(1.4, size * 0.045);
          ctx.strokeStyle = '#292018';
          for (const [ox, heightFrac, fillCol] of spikes) {
            const baseX = tcx + size * ox;
            const baseY = tileY + size * 0.82;
            const halfW = size * 0.13;
            const peakY = baseY - size * heightFrac * rise;
            ctx.fillStyle = fillCol;
            ctx.beginPath();
            ctx.moveTo(baseX - halfW, baseY);
            ctx.lineTo(baseX, peakY);
            ctx.lineTo(baseX + halfW, baseY);
            ctx.lineTo(baseX - halfW, baseY);
            ctx.fill();
            ctx.stroke();
          }

          // Amber-gold shard spark at central spire tip
          ctx.fillStyle = '#fde047';
          ctx.beginPath();
          ctx.arc(
            tcx,
            tcy - size * 0.18 * rise,
            Math.max(1.5, size * 0.055),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }

      case 'skill_shadow_strike': {
        // Dissipating indigo shadow-smoke puff at originPos (if visible) + twin violet-silver crescent X-slash on targetPos
        if (
          event.originPos &&
          (event.originPos.x !== event.targetPos.x || event.originPos.y !== event.targetPos.y)
        ) {
          const ocx = screenPos.x + (event.originPos.x - event.targetPos.x) * size + size * 0.5;
          const ocy = screenPos.y + (event.originPos.y - event.targetPos.y) * size + size * 0.5;
          ctx.fillStyle = 'rgba(88, 28, 135, 0.36)';
          ctx.beginPath();
          ctx.arc(ocx, ocy, size * (0.14 + 0.24 * progress), 0, Math.PI * 2);
          ctx.fill();

          ctx.lineWidth = Math.max(1.8, size * 0.06);
          ctx.strokeStyle = 'rgba(168, 85, 247, 0.85)';
          ctx.beginPath();
          ctx.arc(ocx, ocy, size * (0.12 + 0.28 * progress), 0, Math.PI * 2);
          ctx.stroke();
        }

        // Shadow burst pool & expanding wraith ring on targetPos
        ctx.fillStyle = 'rgba(126, 34, 206, 0.34)';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.16 + 0.24 * progress), 0, Math.PI * 2);
        ctx.fill();

        ctx.lineWidth = Math.max(2, size * 0.075);
        ctx.strokeStyle = event.isCrit ? '#f43f5e' : '#a855f7';
        ctx.beginPath();
        ctx.arc(cx, cy, size * (0.14 + 0.32 * progress), 0, Math.PI * 2);
        ctx.stroke();

        // Twin crossed diagonal violet-silver ambush blades (X-slash)
        const sweep = Math.min(1, progress * 1.55);
        const reach = size * 0.38;
        ctx.lineWidth = Math.max(3, size * 0.11);
        ctx.strokeStyle = event.isCrit ? '#e11d48' : '#c084fc';
        ctx.beginPath();
        ctx.moveTo(cx - reach, cy - reach);
        ctx.lineTo(cx - reach + reach * 2 * sweep, cy - reach + reach * 2 * sweep);
        ctx.moveTo(cx + reach, cy - reach);
        ctx.lineTo(cx + reach - reach * 2 * sweep, cy - reach + reach * 2 * sweep);
        ctx.stroke();

        ctx.lineWidth = Math.max(1.4, size * 0.05);
        ctx.strokeStyle = event.isCrit ? '#fde047' : '#f8fafc';
        ctx.beginPath();
        ctx.moveTo(cx - reach, cy - reach);
        ctx.lineTo(cx - reach + reach * 2 * sweep, cy - reach + reach * 2 * sweep);
        ctx.moveTo(cx + reach, cy - reach);
        ctx.lineTo(cx + reach - reach * 2 * sweep, cy - reach + reach * 2 * sweep);
        ctx.stroke();

        // Dispersing cyan-violet shadow motes
        const moteDist = size * (0.1 + 0.32 * progress);
        for (let i = 0; i < 6; i++) {
          const angle = (i * Math.PI) / 3 + 0.35;
          ctx.fillStyle = i % 2 === 0 ? '#67e8f9' : '#d8b4fe';
          ctx.beginPath();
          ctx.arc(
            cx + Math.cos(angle) * moteDist,
            cy + Math.sin(angle) * moteDist,
            Math.max(1.4, size * 0.05 * (1 - 0.25 * progress)),
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
        break;
      }
    }

    ctx.restore();
  }
}
