  /**
   * Generates a 32x32 colored potion flask sprite for any curated or procedurally synthesized color.
   */
  private createTintedPotionBitmap(
    liquidRgb: readonly [number, number, number],
    highlightRgb: readonly [number, number, number]
  ): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [28, 24, 38, 255];
    const cork: RGBA = [176, 118, 68, 255];
    const glassRim: RGBA = [200, 224, 245, 255];
    const glassUpper: RGBA = [156, 182, 212, 215];
    const liquidColor: RGBA = [liquidRgb[0], liquidRgb[1], liquidRgb[2], 255];
    const liquidHighlight: RGBA = [highlightRgb[0], highlightRgb[1], highlightRgb[2], 255];
    const liquidShadow: RGBA = [
      Math.max(0, Math.round(liquidRgb[0] * 0.72)),
      Math.max(0, Math.round(liquidRgb[1] * 0.72)),
      Math.max(0, Math.round(liquidRgb[2] * 0.72)),
      255,
    ];

    // Subtle ground shadow
    fillRect(data, 10, 25, 12, 2, [0, 0, 0, 105]);

    // Cork & bottle neck
    fillRect(data, 14, 6, 4, 3, cork);
    fillRect(data, 13, 9, 6, 2, glassRim);
    fillRect(data, 13, 11, 6, 3, outline);
    fillRect(data, 14, 11, 4, 3, glassUpper);

    // Rounded flask body
    fillRect(data, 10, 14, 12, 11, outline);
    fillRect(data, 9, 16, 14, 7, outline);
    fillRect(data, 11, 15, 10, 9, liquidColor);
    fillRect(data, 10, 16, 12, 7, liquidColor);
    // Upper empty glass air gap & bottom liquid shadow
    fillRect(data, 11, 15, 10, 1, glassUpper);
    fillRect(data, 11, 22, 10, 2, liquidShadow);
    // Specular highlight on left side of flask
    fillRect(data, 11, 17, 3, 4, liquidHighlight);
    setPixel(data, 12, 16, [255, 255, 255, 235]);
    return { width: 32, height: 32, data };
  }

  /**
   * 32x32 Magic Scroll sprite (Candidate #2: 45° diagonal rolled parchment cylinder with
   * bottom-left spiral coil opening, shaded vellum highlight, crimson ribbon & round wax seal).
   */
  private createScrollItemBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const out: RGBA = [36, 22, 12, 255];
    const creamHi: RGBA = [254, 244, 214, 255];
    const cream: RGBA = [238, 216, 168, 255];
    const tanSh: RGBA = [188, 152, 102, 255];
    const coilDark: RGBA = [78, 50, 26, 255];
    const red: RGBA = [220, 44, 56, 255];
    const redHi: RGBA = [255, 118, 124, 255];
    const redSh: RGBA = [152, 24, 34, 255];

    fillRect(data, 8, 26, 16, 2, [0, 0, 0, 105]);

    // Diagonal cylinder outline & shaded vellum body from bottom-left (8, 22) to top-right (24, 6)
    for (let t = 0; t <= 16; t++) {
      const cx = 8 + t;
      const cy = 22 - t;
      for (let dy = -3; dy <= 3; dy++) {
        for (let dx = -3; dx <= 3; dx++) {
          if (Math.abs(dx) + Math.abs(dy) <= 4) {
            setPixel(data, cx + dx, cy + dy, out);
          }
        }
      }
    }
    for (let t = 0; t <= 16; t++) {
      const cx = 8 + t;
      const cy = 22 - t;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          if (Math.abs(dx) + Math.abs(dy) <= 3) {
            const shade = dx + dy;
            const col = shade <= -1 ? creamHi : shade <= 1 ? cream : tanSh;
            setPixel(data, cx + dx, cy + dy, col);
          }
        }
      }
    }

    // Bottom-left spiral roll cross-section opening (centered at 8, 22)
    fillRect(data, 5, 19, 7, 7, out);
    fillRect(data, 6, 20, 5, 5, tanSh);
    fillRect(data, 7, 21, 3, 3, coilDark);
    setPixel(data, 7, 20, creamHi);
    setPixel(data, 6, 21, creamHi);
    setPixel(data, 8, 22, cream);
    setPixel(data, 9, 23, cream);

    // Crimson silk ribbon band + fluttering tails + round wax seal at center (15, 15)
    for (let i = -3; i <= 3; i++) {
      setPixel(data, 15 + i, 15 + i, out);
      setPixel(data, 16 + i, 15 + i, red);
      setPixel(data, 15 + i, 16 + i, redSh);
    }
    fillRect(data, 17, 18, 3, 6, out);
    fillRect(data, 20, 17, 4, 3, out);
    setPixel(data, 18, 18, red);
    setPixel(data, 18, 19, red);
    setPixel(data, 18, 20, redHi);
    setPixel(data, 18, 21, red);
    setPixel(data, 17, 22, red);
    setPixel(data, 20, 18, red);
    setPixel(data, 21, 18, redHi);
    setPixel(data, 22, 18, red);
    setPixel(data, 23, 19, redSh);

    fillRect(data, 13, 13, 6, 6, out);
    fillRect(data, 14, 14, 4, 4, red);
    setPixel(data, 14, 14, redHi);
    setPixel(data, 15, 14, redHi);
    setPixel(data, 16, 16, redSh);
    setPixel(data, 17, 17, redSh);

    return { width: 32, height: 32, data };
  }

