  private createFeatherlightHoodBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const outline: RGBA = [40, 30, 16, 255];
    const goldCloth: RGBA = [242, 202, 68, 255];
    const lightTrim: RGBA = [255, 240, 156, 255];
    const innerShadow: RGBA = [48, 42, 58, 255];

    fillRect(data, 8, 26, 16, 2, [0, 0, 0, 95]);
    fillRect(data, 8, 7, 16, 18, outline);
    fillRect(data, 9, 8, 14, 16, goldCloth);
    fillRect(data, 10, 8, 12, 3, lightTrim);
    fillRect(data, 12, 12, 8, 9, innerShadow);
    return { width: 32, height: 32, data };
  }

