    fillRect(data, 5, 16, 5, 5, out);
    fillRect(data, 6, 17, 4, 3, skinDark);
    fillRect(data, 2, 13, 7, 7, out);
    fillRect(data, 3, 14, 5, 5, skinOlive);
    fillRect(data, 3, 14, 4, 2, skinHi);
    setPixel(data, 4, 15, eye);
    setPixel(data, 5, 15, out);
    setPixel(data, 2, 18, rimGold);

    // Front & rear near elephantine legs + white toe claws (y = 21..27)
    fillRect(data, 8, 21, 5, 7, out);
    fillRect(data, 9, 22, 3, 5, skinOlive);
    setPixel(data, 9, 22, skinHi);
    setPixel(data, 8, 27, claw);
    setPixel(data, 10, 27, claw);

    fillRect(data, 19, 21, 5, 7, out);
    fillRect(data, 20, 22, 3, 5, skinOlive);
    setPixel(data, 20, 22, skinHi);
    setPixel(data, 19, 27, claw);
    setPixel(data, 21, 27, claw);

    return { width: 32, height: 32, data };
