    // Near-side thick pillar legs + pale hooves
    fillRect(data, 9, 21, 5, 8, out);
    fillRect(data, 10, 21, 3, 6, hideMid);
    fillRect(data, 10, 27, 3, 1, hoof);
    fillRect(data, 23, 21, 5, 8, out);
    fillRect(data, 24, 21, 3, 6, hideMid);
    fillRect(data, 24, 27, 3, 1, hoof);

