  /**
   * 32x32 Rock Pierce magic skill icon ('skill_rock_pierce' / '岩突'):
   * Three ascending jagged obsidian-sandstone spires erupting in a diagonal line with amber geomantic glow.
   */
  private createSkillRockPierceBitmap(): SpriteBitmap {
    const data = new Uint8ClampedArray(SPRITE_BASE_SIZE * SPRITE_BASE_SIZE * 4);
    const out: RGBA = [18, 14, 12, 255];
    const rockDark: RGBA = [72, 58, 46, 255];
    const rockMid: RGBA = [138, 108, 70, 255];
    const rockHi: RGBA = [204, 166, 108, 255];
    const amber: RGBA = [245, 158, 11, 255];
    const gold: RGBA = [253, 224, 71, 255];

    // Glowing ground fissure line at base
    fillRect(data, 3, 25, 26, 3, out);
    fillRect(data, 4, 26, 24, 1, amber);

    // Three sequentially taller erupting stone-pile spires from left to right!
    const spires: ReadonlyArray<[number, number, number, number]> = [
      [4, 16, 7, 10],
      [11, 11, 8, 15],
      [19, 5, 9, 21],
    ];
    for (const [bx, topY, w, h] of spires) {
      for (let dy = 0; dy < h; dy++) {
        const y = topY + dy;
        const frac = (dy + 1) / h;
        const rowW = Math.max(2, Math.round(w * frac));
        const startX = bx + Math.floor((w - rowW) / 2);
        for (let rx = 0; rx < rowW; rx++) {
          const x = startX + rx;
          if (rx === 0 || rx === rowW - 1 || dy === 0) {
            setPixel(data, x, y, out);
          } else if (dy <= 2) {
            setPixel(data, x, y, gold);
          } else if (rx < rowW / 2) {
            setPixel(data, x, y, rockHi);
          } else if (rx === rowW - 2) {
            setPixel(data, x, y, rockDark);
          } else {
            setPixel(data, x, y, rockMid);
          }
        }
      }
    }
    setPixel(data, 7, 15, gold);
    setPixel(data, 15, 10, gold);
    setPixel(data, 23, 4, gold);

    return { width: 32, height: 32, data };
  }

