    fillRect(data, 9, 22, 3, 5, sandstone);
    setPixel(data, 8, 28, fang);
    setPixel(data, 10, 28, fang);

    fillRect(data, 17, 22, 5, 7, out);
    fillRect(data, 18, 22, 3, 5, basaltMid);
    setPixel(data, 17, 28, fang);
    setPixel(data, 19, 28, fang);

    // Horned dragon head jutting left (x = 1..11, y = 5..14)
    fillRect(data, 8, 5, 5, 3, out);
    fillRect(data, 9, 6, 3, 1, goldBright);
    fillRect(data, 1, 8, 11, 7, out);
    fillRect(data, 2, 9, 9, 5, sandstone);
    fillRect(data, 6, 10, 2, 2, goldBright);
    setPixel(data, 3, 13, fang);
    setPixel(data, 6, 13, fang);

    return { width: 32, height: 32, data };
