export type EnemyDeserializer = (data: SerializedEnemy) => Enemy;
export type EnemySpawnFactory = (id: string, position: Point) => Enemy;

export interface NaturalSpawnEnemyEntry {
  readonly archetypeId: string;
  readonly level: number;
  readonly create: EnemySpawnFactory;
}

export interface FloorEnemySpawnProbability {
  readonly archetypeId: string;
  readonly level: number;
  readonly weight: number;
  readonly probability: number;
}

export interface FloorRawMaterialSpawnProbability {
  readonly itemTypeId: string;
  readonly sourceArchetypeId: string;
  readonly level: number;
  readonly probability: number;
}

export interface WizardEnemyDescriptor {
  readonly archetypeId: string;
  readonly name: string;
  readonly spriteKey: string;
  readonly level: number;
  readonly xpReward: number;
  readonly dropsMeat: boolean;
  readonly meatSatietyValue: number;
  readonly meatWeight: number;
  readonly create: EnemySpawnFactory;
}

const enemyDeserializerRegistry = new Map<string, EnemyDeserializer>();
const enemySpawnFactoryRegistry = new Map<string, EnemySpawnFactory>();
const naturalSpawnRegistry = new Map<string, NaturalSpawnEnemyEntry>();

export const DEEP_FLOOR_LOWER_LEVEL_DECAY_SLOPE = 0.35;
export const SPAWN_GROUP_AT_OR_BELOW_WEIGHT = 0.6;
export const SPAWN_GROUP_PLUS_ONE_WEIGHT = 0.3;
export const SPAWN_GROUP_PLUS_TWO_WEIGHT = 0.1;

/**
 * Computes the relative spawn weight factor for `enemyLevel` against `effectiveFloor`:
 * - `enemyLevel <= effectiveFloor` (within-group decay inside the `60%` `<= F` pool): `1 / (1 + 0.35 * (effectiveFloor - enemyLevel))`
 * - `enemyLevel === effectiveFloor + 1`: `0.3` (`30%` group weight)
 * - `enemyLevel === effectiveFloor + 2`: `0.1` (`10%` group weight)
 * - `enemyLevel > effectiveFloor + 2`: `0` (`0%` hard cap)
 */
export function computeEnemyFloorSpawnWeight(enemyLevel: number, effectiveFloor: number): number {
  const diff = enemyLevel - effectiveFloor;
  if (diff <= 0) {
    return 1 / (1 + DEEP_FLOOR_LOWER_LEVEL_DECAY_SLOPE * (effectiveFloor - enemyLevel));
  }
  if (diff === 1) {
    return SPAWN_GROUP_PLUS_ONE_WEIGHT;
  }
  if (diff === 2) {
    return SPAWN_GROUP_PLUS_TWO_WEIGHT;
  }
  return 0;
}

/**
 * Registers an enemy archetype into the natural dungeon spawn pool (`createWeightedEnemy`).
 */
export function registerNaturalSpawnEnemy(entry: NaturalSpawnEnemyEntry): void {
  naturalSpawnRegistry.set(entry.archetypeId, entry);
}

/**
 * Computes the normalized spawn probabilities across all natural dungeon enemies for `floorNumber` (`>= 1`):
 * - Clamps `effectiveFloor = min(floorNumber, maxRegisteredEnemyLevel)`.
 * - Allocates `60%` to `enemyLevel <= effectiveFloor` (distributed across tiers via `1 / (1 + 0.35 * (effectiveFloor - L))`),
 *   `30%` to `enemyLevel === effectiveFloor + 1`, `10%` to `enemyLevel === effectiveFloor + 2`, and `0%` to `enemyLevel > effectiveFloor + 2`.
 * - Splits each level tier's weight evenly across its registered species (`1 / countAtLevel`) and renormalizes active non-empty buckets (Option A).
 */
export function getFloorEnemySpawnProbabilities(floorNumber = 1): FloorEnemySpawnProbability[] {
  const entries = Array.from(naturalSpawnRegistry.values());
  if (entries.length === 0) {
    return [];
  }
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  let maxEnemyLevel = 1;
  const levelCounts = new Map<number, number>();
  for (const entry of entries) {
    if (entry.level > maxEnemyLevel) {
      maxEnemyLevel = entry.level;
    }
    levelCounts.set(entry.level, (levelCounts.get(entry.level) ?? 0) + 1);
  }
  const effectiveFloor = Math.min(safeFloor, maxEnemyLevel);

  let sumAtOrBelowDecay = 0;
  for (const [lvl, count] of levelCounts.entries()) {
    if (count > 0 && lvl <= effectiveFloor) {
      sumAtOrBelowDecay += computeEnemyFloorSpawnWeight(lvl, effectiveFloor);
    }
  }

  let totalWeight = 0;
  const weighted = entries.map((entry) => {
    const countAtLevel = Math.max(1, levelCounts.get(entry.level) ?? 1);
    let tierGroupWeight = 0;
    if (entry.level <= effectiveFloor) {
      tierGroupWeight =
        sumAtOrBelowDecay > 0
          ? SPAWN_GROUP_AT_OR_BELOW_WEIGHT *
            (computeEnemyFloorSpawnWeight(entry.level, effectiveFloor) / sumAtOrBelowDecay)
          : 0;
    } else if (entry.level === effectiveFloor + 1) {
      tierGroupWeight = SPAWN_GROUP_PLUS_ONE_WEIGHT;
    } else if (entry.level === effectiveFloor + 2) {
      tierGroupWeight = SPAWN_GROUP_PLUS_TWO_WEIGHT;
    } else {
      tierGroupWeight = 0;
    }
    const weight = tierGroupWeight / countAtLevel;
    totalWeight += weight;
    return { entry, weight };
  });

  return weighted.map(({ entry, weight }) => ({
    archetypeId: entry.archetypeId,
    level: entry.level,
    weight,
    probability: totalWeight > 0 ? weight / totalWeight : 1 / entries.length,
  }));
}

/**
 * Floor-aware weighted factory for spawning a natural dungeon enemy instance (`roll` in `[0, 1)`):
 * Uses `getFloorEnemySpawnProbabilities(floorNumber)` (`60%` `<= F`, `30%` `F + 1`, `10%` `F + 2`, `0%` `> F + 2`)
 * and skips `0`-probability tiers so `L > F + 2` enemies can never spawn even at floating-point boundary rolls.
 */
export function createWeightedEnemy(
  id: string,
  position: Point,
  roll: number,
  floorNumber = 1
): Enemy {
  const entries = Array.from(naturalSpawnRegistry.values());
  if (entries.length === 0) {
    return new Chick({ id, position });
  }
  const activeProbs = getFloorEnemySpawnProbabilities(floorNumber).filter(
    (p) => p.probability > 0
  );
  if (activeProbs.length === 0) {
    return entries[0].create(id, position);
  }
  const clampedRoll = Math.max(0, Math.min(0.999999999, roll));

  let cumulative = 0;
  for (let i = 0; i < activeProbs.length; i++) {
    cumulative += activeProbs[i].probability;
    if (clampedRoll < cumulative || i === activeProbs.length - 1) {
      const target =
        naturalSpawnRegistry.get(activeProbs[i].archetypeId) ?? entries[entries.length - 1];
      return target.create(id, position);
    }
  }
  return entries[0].create(id, position);
}

/**
 * Computes normalized dungeon floor spawn probabilities across all 44 raw monster materials:
 * - Allocates each enemy species' total floor weight according to `getFloorEnemySpawnProbabilities(floorNumber)`
 *   (`60%` `<= F`, `30%` `F + 1`, `10%` `F + 2`, `0%` `> F + 2` with Option A renormalization).
 * - Splits each species' weight across its raw materials proportional to their `dropChance`s.
 */
export function getFloorRawMaterialSpawnProbabilities(
  floorNumber = 1
): FloorRawMaterialSpawnProbability[] {
  const enemyProbs = getFloorEnemySpawnProbabilities(floorNumber);
  const rawEntries: Array<{
    itemTypeId: string;
    sourceArchetypeId: string;
    level: number;
    rawWeight: number;
  }> = [];
  let totalWeight = 0;

  for (const ep of enemyProbs) {
    const specs = getRawMaterialSpecsForArchetype(ep.archetypeId);
    if (specs.length === 0) {
      continue;
    }
    const sumDrops = specs.reduce((acc, s) => acc + Math.max(0, s.dropChance ?? 0), 0);
    for (const spec of specs) {
      const share = sumDrops > 0 ? Math.max(0, spec.dropChance ?? 0) / sumDrops : 1 / specs.length;
      const rawWeight = ep.probability * share;
      totalWeight += rawWeight;
      rawEntries.push({
        itemTypeId: spec.itemTypeId,
        sourceArchetypeId: ep.archetypeId,
        level: ep.level,
        rawWeight,
      });
    }
  }

  return rawEntries.map((entry) => ({
    itemTypeId: entry.itemTypeId,
    sourceArchetypeId: entry.sourceArchetypeId,
    level: entry.level,
    probability: totalWeight > 0 ? entry.rawWeight / totalWeight : 0,
  }));
}

/**
 * Floor-aware weighted factory for spawning a raw monster material on the dungeon floor (`roll` in `[0, 1)`).
 */
export function createWeightedFloorRawMaterial(
  id: string,
  position: Point,
  roll: number,
  floorNumber = 1
): BaseEquipmentPiece {
  const active = getFloorRawMaterialSpawnProbabilities(floorNumber).filter(
    (p) => p.probability > 0
  );
  if (active.length === 0) {
    return new ChickBone({ id, position });
  }
  const clampedRoll = Math.max(0, Math.min(0.999999999, roll));
  let cumulative = 0;
  for (let i = 0; i < active.length; i++) {
    cumulative += active[i].probability;
    if (clampedRoll < cumulative || i === active.length - 1) {
      return createMonsterEquipmentById(active[i].itemTypeId, { id, position });
    }
  }
  return createMonsterEquipmentById(active[0].itemTypeId, { id, position });
}

function buildStubSerializedEnemy(archetypeId: string, id: string, position: Point): SerializedEnemy {
  return {
    archetypeId,
    sensingRange: DEFAULT_ENEMY_SENSING_RANGE,
    canOpenDoors: false,
    scoreValue: DEFAULT_ENEMY_SCORE_VALUE,
    dropsMeat: true,
    meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
    meatSatietyValue: DEFAULT_ENEMY_MEAT_SATIETY,
    meatWeight: DEFAULT_ENEMY_MEAT_WEIGHT,
    actorState: {
      id,
      name: archetypeId,
      spriteKey: archetypeId,
      position: { ...position },
      level: 1,
      xp: 0,
      baseAttributes: { str: 10, con: 10, int: 10, wis: 10, agi: 10, luk: 10 },
      attributeBonuses: {},
      attributeXp: { str: 0, con: 0, int: 0, wis: 0, agi: 0, luk: 0 },
      growthConfig: { base: 10, slope: 6 },
      enableAttributeGrowth: false,
      hp: 10,
      mp: 0,
      sp: 100,
      sightRadius: 6,
      nextActionTime: 0,
      lastActionSpRegenMultiplier: 1,
      hpRegenAccumulator: 0,
      mpRegenAccumulator: 0,
      spRegenAccumulator: 0,
      inventory: [],
    },
  };
}

/**
 * Registers a concrete Enemy subclass deserializer under its `archetypeId`.
 * Future enemy classes only need to register here to gain full Save/Load support
 * AND automatic discovery in developer Wizard Mode.
 */
export function registerEnemyDeserializer(
  archetypeId: string,
  deserializer: EnemyDeserializer,
  spawnFactory?: EnemySpawnFactory
): void {
  enemyDeserializerRegistry.set(archetypeId, deserializer);
  enemySpawnFactoryRegistry.set(
    archetypeId,
    spawnFactory ?? ((id, position) => deserializer(buildStubSerializedEnemy(archetypeId, id, position)))
  );
}

/**
 * Returns auto-discovered metadata and spawn factories for all registered enemy archetypes.
 */
export function getRegisteredWizardEnemies(): WizardEnemyDescriptor[] {
  const entries: WizardEnemyDescriptor[] = [];
  for (const [archetypeId, create] of enemySpawnFactoryRegistry.entries()) {
    const sample = create(`sample_${archetypeId}`, { x: 0, y: 0 });
    entries.push({
      archetypeId,
      name: sample.name,
      spriteKey: sample.spriteKey,
      level: sample.level,
      xpReward: sample.xpReward,
      dropsMeat: sample.dropsMeat,
      meatSatietyValue: sample.meatSatietyValue,
      meatWeight: sample.meatWeight,
      create,
    });
  }
  return entries;
}

/**
 * Reconstructs a concrete `Enemy` subclass instance from `SerializedEnemy` data,
 * restoring its full Actor state (Level, HP, MP, SP, timeline timestamp, inventory, etc.).
 */
export function deserializeEnemy(data: SerializedEnemy): Enemy {
  const factory = enemyDeserializerRegistry.get(data.archetypeId);
  let enemy: Enemy;
  if (factory) {
    enemy = factory(data);
  } else {
    enemy = new Enemy({
      id: data.actorState.id,
      archetypeId: data.archetypeId,
      name: data.actorState.name,
      position: { ...data.actorState.position },
      spriteKey: data.actorState.spriteKey,
      level: data.actorState.level ?? 1,
      xpReward: data.xpReward,
      sensingRange: data.sensingRange,
      canOpenDoors: data.canOpenDoors,
      avoidsTraps: data.avoidsTraps,
      scoreValue: data.scoreValue,
      dropsMeat: data.dropsMeat,
      meatDropChance: data.meatDropChance,
      meatSatietyValue: data.meatSatietyValue,
      meatWeight: data.meatWeight,
      attributes: data.actorState.baseAttributes,
      stats: data.actorState.customStatOverrides,
    });
  }
  enemy.restoreActorSaveState(data.actorState);
  if (typeof data.alertedTurns === 'number' && data.alertedTurns > 0) {
    enemy.setAlertedTurns(data.alertedTurns);
  }
  return enemy;
}

