export const LEVEL_VITAL_MULTIPLIER_PER_LEVEL = 0.1;

/**
 * Computes the character level multiplier applied to base Max HP, Max MP, and Max SP:
 * LevelMult(L) = 1 + 0.10 * (L - 1)  (1.0x at Lv. 1, 1.1x at Lv. 2, 1.2x at Lv. 3, ...)
 */
export function computeLevelVitalMultiplier(level: number): number {
  const safeLevel = Math.max(1, Math.floor(level));
  return 1 + LEVEL_VITAL_MULTIPLIER_PER_LEVEL * (safeLevel - 1);
}

/**
 * Computes experience required to advance from character level `level` to `level + 1`:
 * xpToNextLevel(L) = 20 * L + 20 * L^2  (Lv. 1->2: 40, 2->3: 120, 3->4: 240, ...)
 */
export function computeXpToNextLevel(level: number): number {
  const safeLevel = Math.max(1, Math.floor(level));
  return 20 * safeLevel + 20 * safeLevel * safeLevel;
}

/**
 * Parameterized linear XP requirement for increasing `currentBaseLevel` to `currentBaseLevel + 1`:
 * xpRequired(L) = max(1, round(base + slope * L))
 */
export function computeAttributeXpRequired(
  currentBaseLevel: number,
  config: AttributeGrowthConfig = DEFAULT_ATTRIBUTE_GROWTH_CONFIG
): number {
  return Math.max(1, Math.round(config.base + config.slope * currentBaseLevel));
}

export type SpRegenMultiplier = 0 | 0.5 | 1;

export const INITIAL_SATIETY = 900;
export const MAX_SATIETY = 1500;
export const FULL_SATIETY_THRESHOLD = 1200;
export const HUNGRY_SATIETY_THRESHOLD = 300;
export const WEAK_SATIETY_THRESHOLD = 100;
export const STARVING_SATIETY_THRESHOLD = 0;
export const FAINT_SATIETY_THRESHOLD = STARVING_SATIETY_THRESHOLD;
export const STARVATION_DEATH_THRESHOLD = -100;

export const BASE_SATIETY_DRAIN_PER_100_TICKS = 1.0;
export const REGEN_POOL_SATIETY_DRAIN_PER_100_TICKS = 0.5;

export const FAINT_PROC_PROBABILITY = 0.2;
export const FAINT_MIN_TURNS = 3;
export const FAINT_MAX_TURNS = 10;

export const BLEEDING_MAX_HP_RATIO = 0.03;
export const MIN_BLEEDING_TURN_DAMAGE = 2;

/**
 * Computes unmitigated HP lost at the end of a bleeding actor's turn:
 * `max(2, round(maxHp * 0.03))` (3% of Max HP, minimum 2 HP).
 */
export function computeBleedingTurnDamage(maxHp: number): number {
  return Math.max(MIN_BLEEDING_TURN_DAMAGE, Math.round(Math.max(1, maxHp) * BLEEDING_MAX_HP_RATIO));
}

export const MIN_SHIELD_DEFENSE_BONUS = 5;
export const SHIELD_DEFENSE_BONUS_RATIO = 0.5;

/**
 * Computes the flat physical defense bonus granted by the `Shield` (`鐵壁`) buff:
 * `max(5, round(unbuffedPhysicalDefense * 0.5))` (+50% DEF, minimum +5 DEF).
 */
export function computeShieldDefenseBonus(unbuffedPhysicalDefense: number): number {
  return Math.max(
    MIN_SHIELD_DEFENSE_BONUS,
    Math.round(Math.max(0, unbuffedPhysicalDefense) * SHIELD_DEFENSE_BONUS_RATIO)
  );
}

/**
 * Computes effective `physicalDefense` after applying `Shield` (+50% DEF, min +5)
 * followed by `Armor Break` (`floor(def * 0.5)`).
 */
export function computeEffectivePhysicalDefense(
  unbuffedPhysicalDefense: number,
  hasShield: boolean,
  hasArmorBreak: boolean
): number {
  const shielded = hasShield
    ? unbuffedPhysicalDefense + computeShieldDefenseBonus(unbuffedPhysicalDefense)
    : unbuffedPhysicalDefense;
  return hasArmorBreak ? Math.floor(shielded * 0.5) : shielded;
}

export type SatietyState = 'full' | 'normal' | 'hungry' | 'weak' | 'starving' | 'starved';
export type SpecialEffectId =
  | 'full'
  | 'hungry'
  | 'weak'
  | 'starving'
  | 'faint'
  | 'burdened'
  | 'paralysis'
