  /**
   * Permanently increases `attr` by `delta` (`>= 1`), resets `attributeXp[attr] = 0`
   * (leaving XP on all other attributes untouched), and recalculates derived stats while preserving vitals.
   */
  public growAttributeAndResetXp(
    attr: PrimaryAttributeKey,
    delta = 1
  ): { oldValue: number; newValue: number } {
    const inc = Math.max(1, Math.round(delta));
    const oldValue = this.baseAttributes[attr];
    const newValue = oldValue + inc;
    this.baseAttributes = {
      ...this.baseAttributes,
      [attr]: newValue,
    };
    this.attributeXp[attr] = 0;
    this.recalculateStats(false);
    return { oldValue, newValue };
  }

