import { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { Action, ActionResult } from './Action';

/**
 * Executes an adjacent War Skill (`'bite'`, `'pierce'`, etc.) performed by an `Enemy` (or non-player `Actor`)
 * against `target` via `world.executeEnemyWarSkill`.
 */
export class WarSkillAction implements Action {
  public readonly type = 'war_skill';
  public readonly target: Actor;
  public readonly skillId: string;

  constructor(target: Actor, skillId: string) {
    this.target = target;
    this.skillId = skillId;
  }

  public execute(attacker: Actor, world: GameWorld): ActionResult {
    return world.executeEnemyWarSkill(attacker, this.target, this.skillId);
  }
}
