export const ALL_MONSTER_EQUIPMENT_SPECS: readonly MonsterEquipmentSpec[] = [
  ...MONSTER_RAW_MATERIAL_SPECS,
  ...CRAFTED_MONSTER_GEAR_SPECS,
];

const monsterEquipmentClassesById = new Map<string, MonsterEquipmentConstructor>();
const monsterEquipmentSpecsById = new Map<string, MonsterEquipmentSpec>();
const rawMaterialSpecsByArchetype = new Map<string, MonsterEquipmentSpec[]>();

function defineEquipmentClass(spec: MonsterEquipmentSpec): MonsterEquipmentConstructor {
  class GeneratedEquipmentPiece extends BaseEquipmentPiece {
    constructor(options: EquipmentPieceOptions) {
      super(spec, options);
    }

    public override cloneWithAmount(
      newAmount: number,
      newId?: string
    ): GeneratedEquipmentPiece {
      return new GeneratedEquipmentPiece(this.buildCloneOptions(newAmount, newId));
    }
  }
  Object.defineProperty(GeneratedEquipmentPiece, 'name', { value: spec.className });
  monsterEquipmentClassesById.set(spec.itemTypeId, GeneratedEquipmentPiece);
  monsterEquipmentSpecsById.set(spec.itemTypeId, spec);
  if (spec.isRawMaterial && spec.sourceArchetypeId) {
    const list = rawMaterialSpecsByArchetype.get(spec.sourceArchetypeId) ?? [];
    list.push(spec);
    rawMaterialSpecsByArchetype.set(spec.sourceArchetypeId, list);
  }
  return GeneratedEquipmentPiece;
}

for (const spec of ALL_MONSTER_EQUIPMENT_SPECS) {
  defineEquipmentClass(spec);
}

function getCls(itemTypeId: string): MonsterEquipmentConstructor {
  const cls = monsterEquipmentClassesById.get(itemTypeId);
  if (!cls) {
    throw new Error(`Missing MonsterEquipmentConstructor for ${itemTypeId}`);
  }
  return cls;
}

export function getMonsterEquipmentSpecById(itemTypeId: string): MonsterEquipmentSpec | undefined {
  return monsterEquipmentSpecsById.get(itemTypeId);
}

export function getMonsterEquipmentConstructorById(
  itemTypeId: string
): MonsterEquipmentConstructor | undefined {
  return monsterEquipmentClassesById.get(itemTypeId);
}

export function createMonsterEquipmentById(
  itemTypeId: string,
  options: EquipmentPieceOptions
): BaseEquipmentPiece {
  const Cls = getCls(itemTypeId);
  return new Cls(options);
}

export function getRawMaterialSpecsForArchetype(
  archetypeId: string
): readonly MonsterEquipmentSpec[] {
  return rawMaterialSpecsByArchetype.get(archetypeId) ?? [];
}

/**
 * Builds the `EnemyTrophyDropEntry[]` array for a given `archetypeId` directly from `MONSTER_RAW_MATERIAL_SPECS`.
 */
export function buildEnemyRawMaterialDrops(archetypeId: string): Array<{
  readonly itemTypeId: string;
  readonly chance: number;
  readonly create: (options: { readonly id: string; readonly position: Point }) => BaseEquipmentPiece;
}> {
  return getRawMaterialSpecsForArchetype(archetypeId).map((spec) => ({
    itemTypeId: spec.itemTypeId,
    chance: spec.dropChance ?? 0.25,
    create: ({ id, position }) => createMonsterEquipmentById(spec.itemTypeId, { id, position }),
  }));
}

